Qualtrics.SurveyEngine.addOnReady(function () {
  var q = this;
  var container = q.getQuestionTextContainer ? q.getQuestionTextContainer() : document;
  var range = container.querySelector('#qsRange');
  var bubble = container.querySelector('#qsBubble');
  var fill = container.querySelector('#qsFill');
  var reading = container.querySelector('#qsReading');

  // Hide the built-in text entry input and use it to store the value
  var textInput = q.getQuestionContainer().querySelector('input[type="text"], input.InputText');
  if (textInput) {
    textInput.style.display = 'none';
    textInput.value = range.value; // ensure a value is recorded even if untouched
  }

  function phrase(v) {
    v = Number(v);
    if (v === 50) return "I have no idea which candidate will perform better";
    if (v <= 15) return "I am very confident Candidate B will perform better";
    if (v < 50)  return "I think Candidate B will perform better, but I'm not very confident";
    if (v >= 85) return "I am very confident Candidate A will perform better";
    return "I think Candidate A will perform better, but I'm not very confident";
  }

  function setBubblePosition(val) {
    var min = Number(range.min), max = Number(range.max);
    var pct = (val - min) / (max - min);
    // Position bubble and fill
    bubble.style.left = (pct * 100) + "%";
    fill.style.width = (pct * 100) + "%";
    // Update ARIA value
    range.setAttribute('aria-valuenow', String(val));
  }

  function update() {
    var v = Number(range.value);
    bubble.textContent = v;
    reading.textContent = v + " — " + phrase(v);
    if (textInput) textInput.value = v;
    Qualtrics.SurveyEngine.setEmbeddedData('endorsement_slider', v);
    setBubblePosition(v);
  }

  // Keyboard: Arrow keys (±1), Shift+Arrows (±5)
  range.addEventListener('keydown', function (e) {
    var step = e.shiftKey ? 5 : 1;
    if (e.key === 'ArrowLeft') { range.value = Math.max(0, Number(range.value) - step); update(); e.preventDefault(); }
    if (e.key === 'ArrowRight'){ range.value = Math.min(100, Number(range.value) + step); update(); e.preventDefault(); }
  });

  range.addEventListener('input', update);
  update(); // initialize

  // Ensure value is saved even if participant never moves the slider
  this.addOnPageSubmit(function () { update(); });
});

