Qualtrics.SurveyEngine.addOnReady(function () {
  "use strict";
  var q = this, $ = window.jQuery;
  var start = Date.now();

  var qc = q.getQuestionContainer();
  var container = q.getQuestionTextContainer ? q.getQuestionTextContainer() : qc;

  var textInput = qc.querySelector('input[type="text"], input.InputText, textarea');
  if (textInput) textInput.style.display = 'none';

  // UI nodes
  var Aimg = container.querySelector('#A_img'),
      Bimg = container.querySelector('#B_img');
  var Ameta = container.querySelector('#A_meta'),
      Bmeta = container.querySelector('#B_meta');
  var AGK = container.querySelector('#A_GK'),
      AW  = container.querySelector('#A_Word');
  var BGK = container.querySelector('#B_GK'),
      BW  = container.querySelector('#B_Word');
  var rng = container.querySelector('#rng'),
      bubble = container.querySelector('#bubble'),
      fill = container.querySelector('#fill'),
      reading = container.querySelector('#reading');

  var ICON = {
    "Woman": "https://wharton.yul1.qualtrics.com/ControlPanel/Graphic.php?IM=IM_rPkPsDPTOJEHbxS",
    "Man":   "https://wharton.yul1.qualtrics.com/ControlPanel/Graphic.php?IM=IM_2XVqkTCg6PGauA7"
  };

  function ordinal(n){
    n = Number(n);
    if (!isFinite(n)) return "Unknown";
    var s=["th","st","nd","rd"], v=n%100;
    return n + (s[(v-20)%10] || s[v] || s[0]);
  }
  function setPercentile(el, val){
    if (val === null || val === undefined || String(val).toLowerCase() === "unknown"){
      el.textContent = "Unknown";
      el.classList.add("unknown");
    } else {
      el.textContent = ordinal(val) + " percentile";
      el.classList.remove("unknown");
    }
  }

  // Stimulus pool (unchanged)
  var STIM = [
    {pair_id:'dominant_A', category:'Dominant',
      A:{id:'zlrgipzx', gender:'Woman', GK:97, Word:99},
      B:{id:'wdjc417p', gender:'Man',   GK:3,  Word:5},
      truth:'A', truth_gender:'Woman'
    },
    {pair_id:'obvious_w_fails', category:'ObviousFails_WomanLooksBetter',
      A:{id:'5yrzkge8', gender:'Woman', GK:100, Word:92},
      B:{id:'1unc8ds8', gender:'Man',   GK:9,   Word:30},
      truth:'B', truth_gender:'Man'
    },
    {pair_id:'discord_gkM_wW', category:'Discordant_GKfavMan_WordfavWoman',
      A:{id:'musgffcq', gender:'Man',   GK:41, Word:47},
      B:{id:'i7u34n0x', gender:'Woman', GK:3,  Word:78},
      truth:'A', truth_gender:'Man'
    },
    {pair_id:'discord_gkW_wM', category:'Discordant_GKfavWoman_WordfavMan',
      A:{id:'aoygoszl', gender:'Woman', GK:75, Word:1},
      B:{id:'49ki2ruu', gender:'Man',   GK:17, Word:78},
      truth:'B', truth_gender:'Man'
    },
    {pair_id:'close_winsW', category:'Close_WomanWins',
      A:{id:'e9jz82ta', gender:'Woman', GK:75, Word:16},
      B:{id:'fyis6atg', gender:'Man',   GK:80, Word:11},
      truth:'A', truth_gender:'Woman'
    },
    {pair_id:'identical_WW_Bwins', category:'Identical_WomanWoman_Bwins',
      A:{id:'zaken6uy', gender:'Woman', GK:68, Word:72},
      B:{id:'3z86qvov', gender:'Woman', GK:68, Word:72},
      truth:'B', truth_gender:'Woman'
    },
    {pair_id:'unknown_split_ManWins', category:'UnknownsSplit_ManWins',
      A:{id:'gtiak505', gender:'Woman', GK:97, Word:"Unknown"},
      B:{id:'cjivnb9m', gender:'Man',   GK:"Unknown", Word:97},
      truth:'B', truth_gender:'Man'
    },
    {pair_id:'obvious_m_fails', category:'ObviousFails_ManLooksBetter',
      A:{id:'nuunve0a', gender:'Man',   GK:93, Word:92},
      B:{id:'i8823gif', gender:'Woman', GK:28, Word:86},
      truth:'B', truth_gender:'Woman'
    }
  ];

  var trial = STIM[Math.floor(Math.random() * STIM.length)];

  function populate(){
    // Bigger centered icons (alt doesn’t expose gender text to participants)
    Aimg.src = ICON[trial.A.gender]; Aimg.alt = "Candidate A icon";
    Bimg.src = ICON[trial.B.gender]; Bimg.alt = "Candidate B icon";

    // Remove visible gender text: show ID only
    Ameta.textContent = "ID " + trial.A.id;
    Bmeta.textContent = "ID " + trial.B.id;

    // Percentiles as “97th percentile”
    setPercentile(AGK, trial.A.GK); setPercentile(AW, trial.A.Word);
    setPercentile(BGK, trial.B.GK); setPercentile(BW, trial.B.Word);

    // Embedded Data (still includes gender)
    Qualtrics.SurveyEngine.setEmbeddedData('stim_pair_id', trial.pair_id);
    Qualtrics.SurveyEngine.setEmbeddedData('stim_category', trial.category);
    Qualtrics.SurveyEngine.setEmbeddedData('stim_truth', trial.truth);
    Qualtrics.SurveyEngine.setEmbeddedData('stim_truth_gender', trial.truth_gender);

    Qualtrics.SurveyEngine.setEmbeddedData('A_id', trial.A.id);
    Qualtrics.SurveyEngine.setEmbeddedData('A_gender', trial.A.gender);
    Qualtrics.SurveyEngine.setEmbeddedData('A_GK', trial.A.GK);
    Qualtrics.SurveyEngine.setEmbeddedData('A_Word', trial.A.Word);

    Qualtrics.SurveyEngine.setEmbeddedData('B_id', trial.B.id);
    Qualtrics.SurveyEngine.setEmbeddedData('B_gender', trial.B.gender);
    Qualtrics.SurveyEngine.setEmbeddedData('B_GK', trial.B.GK);
    Qualtrics.SurveyEngine.setEmbeddedData('B_Word', trial.B.W
    );
  }

	function interp(v){
		v = Number(v);
		if (v === 50) return "I have no idea which candidate will perform better";
		if (v <= 15)  return "I am very confident Candidate A will perform better";
		if (v < 50)   return "I think Candidate A will perform better, but I'm not very confident";
		if (v >= 85)  return "I am very confident Candidate B will perform better";
		return "I think Candidate B will perform better, but I'm not very confident";
	}

  function update(){
    var v = Number(rng.value);
    bubble.textContent = v;
    bubble.style.left = v + "%";
    fill.style.width = v + "%";
    reading.textContent = v + " — " + interp(v);
    if (textInput) textInput.value = v;
  }

  rng.addEventListener('input', update);
  rng.addEventListener('keydown', function (e) {
    var step = e.shiftKey ? 5 : 1;
    if (e.key === 'ArrowLeft'){ rng.value = Math.max(0, Number(rng.value) - step); update(); e.preventDefault(); }
    if (e.key === 'ArrowRight'){ rng.value = Math.min(100, Number(rng.value) + step); update(); e.preventDefault(); }
  });

  var saved = false;
  function saveResponse(){
    if (saved) return; saved = true;
    var v = Number(rng.value);
    var side = (v > 50) ? 'B' : (v < 50 ? 'A' : 'Neutral');
    Qualtrics.SurveyEngine.setEmbeddedData('slider_value', v);
    Qualtrics.SurveyEngine.setEmbeddedData('slider_side', side);
    Qualtrics.SurveyEngine.setEmbeddedData('rt_ms', Date.now() - start);
    if (textInput) textInput.value = v;
    update();
  }

  $(document).off('click.saveED','#NextButton').on('click.saveED','#NextButton',saveResponse);
  if (typeof q.addOnUnload === 'function'){ q.addOnUnload(saveResponse); }
  else { window.addEventListener('beforeunload', saveResponse); }

  populate();
  update();
});

