        html += '<div class="q-label">Question: ' + items[i].q + '</div>';
        html += '<div class="correct-answer">Correct answer: ' + items[i].a + '</div>';
        html += '<div class="explanation">' + items[i].why + '</div>';
        html += '</div>';
    }

    container.innerHTML = html;
});

