    var reasons = [];
    if (venus !== "2") { pass = false; reasons.push("venus=" + venus); }
    if (fatal !== "2") { pass = false; reasons.push("fatal=" + fatal); }
    if (water !== "1") { pass = false; reasons.push("water=" + water); }
    if (human !== "1") { pass = false; reasons.push("human=" + human); }
    if (ec2.indexOf("one two") === -1) { pass = false; reasons.push("ec2=" + ec2); }

    Qualtrics.SurveyEngine.setEmbeddedData("attn_pass", pass ? "1" : "0");
    Qualtrics.SurveyEngine.setEmbeddedData("attn_fail_reasons", reasons.join(","));

    this.clickNextButton();
});
